import{_ as t,o as e,c as i,a as o}from"./chunks/framework.fmIt2z2h.js";const r="/xi-kari-skill/handbook/images/history.svg",u=JSON.parse('{"title":"留下记录，与真正学会了什么","description":"学习要看更新怎样保留、怎样被调用；历史是否另有预测增量，是另一个问题。","frontmatter":{"title":"留下记录，与真正学会了什么","description":"学习要看更新怎样保留、怎样被调用；历史是否另有预测增量，是另一个问题。"},"headers":[],"relativePath":"concepts/history.md","filePath":"concepts/history.md"}'),l={name:"concepts/history.md"};function s(h,a,n,c,p,d){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="留下记录-与真正学会了什么" tabindex="-1">留下记录，与真正学会了什么 <a class="header-anchor" href="#留下记录-与真正学会了什么" aria-label="Permalink to &quot;留下记录，与真正学会了什么&quot;">​</a></h1><p>经验写进了档案，为什么还要看下一次有没有用上？</p><p><strong>学习要看更新怎样保留、怎样被调用；历史是否另有预测增量，是另一个问题。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>沿用原文的虚拟申诉例：一次案件处理真的变了，仍要继续看这次变化有没有形成可保留的规则或状态，后来处理相似案件时有没有调用，以及预定任务结果是否出现可复核差异。载体可以是状态、参数、规则、记忆或结构；关键不是名称，而是更新实际进入后续工作。原文又举出较早经历H改变当前技能S、技能再影响结果Y的关系。</p><p>如果当前技能已经充分携带相关历史信息，知道技能之后，完整经历可能不再增加预测信息。这不取消早期经历的作用，也不取消一般学习，只说明“当前状态之外还有多少历史增量”获得了另一种答案。因此，档案存在、载体学习、额外历史增量和最终净收益要分开看，不能把其中一个当作其余几个的证明。</p><figure class="concept-figure"><img src="'+r+'" alt="经验怎样进入下一次任务"><figcaption>这是原文的载体学习机制链；每段都需要相应依据，不能凭归档跨越。</figcaption></figure><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>一次参数变化、一次成功、一次写回或材料归档都不足以证明这条学习机制。</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-04.html#section-4-5">§4.5 历史形成、当前载体与G3条件增量</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">§6.3 CM-LEARNING 反馈介导学习</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-4">§6.4 虚拟申诉例</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>一般学习可以依据领域证据成立，不必先获得本框架正式机制实例身份。学习成立也不等于效果更好；当前技能充分而历史增量消失，不表示过去没有作用。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./feedback.html">收到消息，为什么还不算有效反馈</a></li><li><a href="./chain.html">两段都有效，整条链为什么仍可能无效</a></li></ul>',14)])])}const _=t(l,[["render",s]]);export{u as __pageData,_ as default};
